import test, { beforeEach, after } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import { useTestDb } from "../helpers/db.mjs";

// Content tools generated by the core for every content instance:
//  - `list_entries` / `get_entry` also give the public path (`path`, `paths` per language), additively;
//  - `<instance>__update_published_meta` corrects the summary of a PUBLISHED entry without unpublishing it.
// Invented data only.
// eslint-disable-next-line react-hooks/rules-of-hooks -- useTestDb is not a React hook
const db = await useTestDb();
const T = await import("@/core/services/mcp/tokens");
const { handleMcpRequest } = await import("@/core/services/mcp/server");
const { listMcpTools, listMcpToolCatalogue } = await import("@/core/platform");
const M = await import("@/core/maintenance/actions");
const SL = await import("@/core/maintenance/slots");
const P = await import("@/core/services/mcp/profiles");
const EM = await import("@/core/maintenance/entryMeta");
const { createInstance } = await import("@/core/instanceService");
const { createEntry } = await import("@/core/content/service");
const { setSetting } = await import("@/core/settings");
const { FIXTURE_MODULES } = await import("../helpers/fixtureModules.mjs");

const blog = FIXTURE_MODULES.find((b) => b.manifest.id === "blog").manifest;
let news;

beforeEach(async () => {
  await db.reset();
  M.resetMaintenanceState();
  await setSetting("i18n.default", "en");
  await setSetting("i18n.enabled", ["en", "fr"]);
  await db.fixture("blog");
  news = await createInstance(db.prisma, { manifest: blog, nickname: "News", names: { en: "News" } });
});
after(() => db.close());

const rpc = (token, method, params = {}) => handleMcpRequest(new Request("http://x/api/mcp", { method: "POST", headers: { "content-type": "application/json", authorization: `Bearer ${token}` }, body: JSON.stringify({ jsonrpc: "2.0", id: 1, method, params }) }), listMcpTools);
const listed = async (token) => (await (await rpc(token, "tools/list")).json()).result.tools.map((t) => t.name);
async function call(token, name, args = {}) {
  const body = await (await rpc(token, "tools/call", { name, arguments: args })).json();
  if (body.error) return { error: body.error.message };
  const text = body.result.content[0].text;
  let value; try { value = JSON.parse(text); } catch { value = text; }
  return body.result.isError ? { error: text } : { value };
}
async function access(grant = ["news__update_published_meta", "news__list_entries", "news__get_entry"], scope = "write") {
  const token = await T.createToken("Camille", scope, "owner@example.org", { grants: Object.fromEntries(grant.map((g) => [g, true])) });
  return { token, id: await T.findTokenId(token) };
}
/** An entry written in English and, when asked, in French too. */
async function entry({ frSlug, ...over } = {}, fr = true) {
  const e = await createEntry(db.prisma, { instanceId: news.id, locale: "en", title: "Northern lights", summary: "Old summary", body: "Body text", status: "published", ...over });
  if (fr) await db.prisma.entryTranslation.create({ data: { entryId: e.id, instanceId: news.id, locale: "fr", slug: frSlug ?? "aurores", title: "Aurores", summary: "Ancien resume", body: "Texte" } });
  return e.id;
}
const summaries = async (id) => Object.fromEntries((await db.prisma.entryTranslation.findMany({ where: { entryId: id } })).map((t) => [t.locale, t.summary]));
const audits = () => db.prisma.auditLog.findMany({ where: { action: "entry.meta.update" }, orderBy: { createdAt: "asc" } });

test("list_entries and get_entry: the public path of the entry and of each language, default language without prefix", async () => {
  const id = await entry();
  const { token } = await access();
  const list = (await call(token, "news__list_entries", {})).value;
  assert.equal(list.length, 1);
  assert.equal(list[0].path, "/blog/northern-lights");
  assert.deepEqual(list[0].paths, { en: "/blog/northern-lights", fr: "/fr/blog/aurores" });
  assert.equal(list[0].status, "published");
  for (const k of ["id", "status", "title", "locale", "languages", "summary", "tags", "publishedAt"]) assert.ok(k in list[0], `${k} still there`);
  const fr = (await call(token, "news__list_entries", { locale: "fr" })).value;
  assert.equal(fr[0].locale, "fr");
  assert.equal(fr[0].path, "/fr/blog/aurores");
  const one = (await call(token, "news__get_entry", { id, locale: "fr" })).value;
  assert.equal(one.path, "/fr/blog/aurores");
  assert.deepEqual(one.paths, { en: "/blog/northern-lights", fr: "/fr/blog/aurores" });
  assert.equal(one.body, "Texte");
  const en = (await call(token, "news__get_entry", { id })).value;
  assert.equal(en.path, "/blog/northern-lights");
});

test("paths follow the default language of the site: French without prefix when it is the default", async () => {
  const id = await entry();
  await setSetting("i18n.default", "fr");
  const { token } = await access();
  const one = (await call(token, "news__get_entry", { id })).value;
  assert.equal(one.locale, "fr");
  assert.equal(one.path, "/blog/aurores");
  assert.deepEqual(one.paths, { en: "/en/blog/northern-lights", fr: "/blog/aurores" });
});

test("update_published_meta: tool shape, off by default, separate right; the schema accepts only id, locale and summary", async () => {
  const tool = (await listMcpTools()).find((t) => t.name === "news__update_published_meta");
  assert.deepEqual([tool.readOnly, tool.default, tool.destructive, tool.audited], [false, false, false, true]);
  assert.deepEqual(Object.keys(tool.input.properties).sort(), ["id", "locale", "summary"]);
  assert.deepEqual([...tool.input.required].sort(), ["id", "locale", "summary"]);
  assert.equal(tool.input.properties.summary.maxLength, 2000);
  const plain = await T.createToken("Drafts only", "write", "o");
  assert.ok((await listed(plain)).includes("news__update_draft"));
  assert.ok(!(await listed(plain)).includes("news__update_published_meta"));
  assert.match((await call(plain, "news__update_published_meta", { id: "x", locale: "en", summary: "s" })).error, /Unknown tool/);
  const ro = await access(["news__update_published_meta"], "read");
  assert.ok(!(await listed(ro.token)).includes("news__update_published_meta"), "a read-only ceiling blocks it even when ticked");
});

test("update_published_meta: fixes one language, the entry stays published, nothing else moves", async () => {
  const id = await entry();
  const { token } = await access();
  const before = await db.prisma.entryTranslation.findMany({ where: { entryId: id }, orderBy: { locale: "asc" } });
  const r = await call(token, "news__update_published_meta", { id, locale: "fr", summary: "Nouveau resume" });
  assert.deepEqual([r.value.status, r.value.changed, r.value.locale], ["published", true, "fr"]);
  assert.deepEqual(await summaries(id), { en: "Old summary", fr: "Nouveau resume" });
  const after = await db.prisma.entryTranslation.findMany({ where: { entryId: id }, orderBy: { locale: "asc" } });
  for (const [i, t] of after.entries()) assert.deepEqual([t.slug, t.title, t.body], [before[i].slug, before[i].title, before[i].body], "title, address and text untouched");
  assert.equal((await db.prisma.entry.findUnique({ where: { id } })).status, "published");
  const same = await call(token, "news__update_published_meta", { id, locale: "fr", summary: "Nouveau resume" });
  assert.equal(same.value.changed, false);
  assert.equal((await audits()).length, 1, "no journal line when nothing changed");
});

test("update_published_meta: refuses drafts, other instances, missing languages and anything but id, locale, summary", async () => {
  const draft = await entry({ status: "draft", title: "Draft page", frSlug: "brouillon" });
  const id = await entry();
  const other = await createInstance(db.prisma, { manifest: blog, nickname: "Notes", names: { en: "Notes" } });
  const foreign = (await createEntry(db.prisma, { instanceId: other.id, locale: "en", title: "Elsewhere", summary: "S", status: "published" })).id;
  const { token } = await access();
  assert.match((await call(token, "news__update_published_meta", { id: draft, locale: "en", summary: "x" })).error, /draft.*update_draft/);
  assert.deepEqual(await summaries(draft), { en: "Old summary", fr: "Ancien resume" });
  assert.match((await call(token, "news__update_published_meta", { id: foreign, locale: "en", summary: "x" })).error, /entry not found/);
  assert.match((await call(token, "news__update_published_meta", { id: "nope", locale: "en", summary: "x" })).error, /entry not found/);
  const only = await entry({ title: "Solo", slug: "solo" }, false);
  assert.match((await call(token, "news__update_published_meta", { id: only, locale: "fr", summary: "x" })).error, /no fr version.*en/);
  for (const extra of ["title", "slug", "body", "status", "url", "code", "tags", "ids"]) {
    const r = await call(token, "news__update_published_meta", { id, locale: "en", summary: "x", [extra]: extra === "tags" || extra === "ids" ? ["a"] : "a" });
    assert.match(r.error, new RegExp(`unexpected argument "${extra}"`), extra);
  }
  assert.match((await call(token, "news__update_published_meta", { id, locale: "en" })).error, /missing required argument "summary"/);
  assert.match((await call(token, "news__update_published_meta", { id, locale: "de", summary: "x" })).error, /one of: en, fr/);
  assert.match((await call(token, "news__update_published_meta", { id, locale: "en", summary: "x".repeat(2001) })).error, /at most 2000/);
  assert.equal((await call(token, "news__update_published_meta", { id, locale: "en", summary: "x".repeat(2000) })).value.changed, true);
  assert.equal((await audits()).length, 1);
});

test("update_published_meta: the journal keeps who, what, where and only lengths, never the text", async () => {
  const id = await entry();
  const { token } = await access();
  await call(token, "news__update_published_meta", { id, locale: "en", summary: "Secret new wording" });
  const rows = await audits();
  assert.equal(rows.length, 1);
  assert.deepEqual([rows[0].actor, rows[0].actorKind, rows[0].target, rows[0].instance], ["mcp:Camille", "assistant", `news/${id}`, "news"]);
  assert.deepEqual(JSON.parse(rows[0].data), { locale: "en", lengthBefore: "Old summary".length, lengthAfter: "Secret new wording".length });
  assert.ok(!JSON.stringify(rows).includes("Secret new wording") && !JSON.stringify(rows).includes("Old summary"));
});

test("update_published_meta: the previous value is kept, and restored only while nobody edited since", async () => {
  const id = await entry();
  const { token } = await access();
  await call(token, "news__update_published_meta", { id, locale: "en", summary: "First fix" });
  await call(token, "news__update_published_meta", { id, locale: "en", summary: "Second fix" });
  const points = await EM.loadSummaryUndoPoints();
  assert.equal(points.length, 1, "one point per version: the newest");
  assert.deepEqual([points[0].key, points[0].id, points[0].locale, points[0].previous, points[0].applied, points[0].by], ["news", id, "en", "First fix", "Second fix", "Camille"]);
  assert.ok(Math.abs(points[0].at - Date.now()) < 60_000);
  // a person edits the text afterwards: nothing is restored
  await db.prisma.entryTranslation.updateMany({ where: { entryId: id, locale: "en" }, data: { summary: "Written by a person" } });
  assert.deepEqual(await EM.restoreEntrySummary("news", id, "en"), { ok: false, reason: "changed" });
  assert.equal((await summaries(id)).en, "Written by a person");
  await db.prisma.entryTranslation.updateMany({ where: { entryId: id, locale: "en" }, data: { summary: "Second fix" } });
  assert.deepEqual(await EM.restoreEntrySummary("news", id, "en"), { ok: true });
  assert.equal((await summaries(id)).en, "First fix");
  assert.deepEqual(await EM.restoreEntrySummary("news", id, "en"), { ok: false, reason: "none" });
});

test("update_published_meta: uses the shared everyday counter (class content), 120 per hour by default", async () => {
  const id = await entry();
  const { token, id: tokenId } = await access();
  assert.equal((await SL.remainingSlots(tokenId)).content.used, 0);
  await call(token, "news__update_published_meta", { id, locale: "en", summary: "One" });
  assert.equal((await SL.remainingSlots(tokenId)).content.used, 1);
  assert.equal((await SL.remainingSlots(tokenId)).risky.used, 0);
  await SL.setLimits(tokenId, { content: 10 });
  for (let i = 0; i < 9; i++) await call(token, "news__update_published_meta", { id, locale: "en", summary: `Fix ${i}` });
  assert.match((await call(token, "news__update_published_meta", { id, locale: "en", summary: "Too many" })).error, /Limit reached: 10 content actions per hour/);
});

test("profiles: assigned to the full preset only; the rights page shows it in the publishing section; every tool is classified", async () => {
  const catalogue = await listMcpToolCatalogue();
  assert.deepEqual(catalogue.filter((t) => P.placementOf(t) === "unassigned").map((t) => t.name), []);
  const tool = catalogue.find((t) => t.name === "news__update_published_meta");
  assert.equal(P.placementOf(tool), "full");
  assert.deepEqual(["read", "assistant", "full"].map((p) => P.profileAllows(p, tool)), [false, false, true]);
  assert.equal(P.placementOf(catalogue.find((t) => t.name === "news__update_draft")), "assistant");
});

test("French and English: the rights line and the journal line exist in both languages, same variables, plain words", () => {
  const en = JSON.parse(fs.readFileSync("src/locales/en.json", "utf8"));
  const fr = JSON.parse(fs.readFileSync("src/locales/fr.json", "utf8"));
  const vars = (s) => [...s.matchAll(/\{(\w+)\}/g)].map((m) => m[1]).sort().join(",");
  for (const k of ["aim.tool.update_published_meta", "audit.action.entry.meta.update"]) {
    assert.ok(typeof en[k] === "string" && typeof fr[k] === "string" && fr[k].trim(), k);
    assert.equal(vars(fr[k]), vars(en[k]), `${k}: same variables`);
    assert.ok(!/[!]/.test(en[k] + fr[k]) && !/\b(Veuillez|token|jeton|webhook|slug|payload|JSON|API)\b/i.test(en[k] + fr[k]), `${k}: plain words`);
  }
  assert.match(en["aim.tool.update_published_meta"], /\{name\}/);
});
